-- Result of 2NF + 3NF for the Brightside sheet
CREATE TABLE products (             -- depends on sku only (2NF)
  sku        TEXT PRIMARY KEY,
  name       TEXT NOT NULL,
  list_price NUMERIC(10,2) NOT NULL
);

-- orders and customers as in the first subtopic (3NF split)

CREATE TABLE order_lines (          -- needs the whole key
  order_id   INT  NOT NULL REFERENCES orders (order_id),
  sku        TEXT NOT NULL REFERENCES products (sku),
  qty        INT  NOT NULL CHECK (qty > 0),
  unit_price NUMERIC(10,2) NOT NULL,   -- price charged on this sale
  PRIMARY KEY (order_id, sku)          -- composite key
);

-- Ana moves: one row changes, every order sees it
UPDATE customers SET city = 'York' WHERE email = 'ana@example.com';

-- Junction table for a plain many-to-many (products <-> tags)
CREATE TABLE tags (tag_id INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
                   label TEXT NOT NULL UNIQUE);
CREATE TABLE product_tags (
  sku    TEXT REFERENCES products (sku) ON DELETE CASCADE,
  tag_id INT  REFERENCES tags (tag_id)    ON DELETE CASCADE,
  PRIMARY KEY (sku, tag_id)             -- each pair stored once
);

-- One-to-one: the primary key is also the foreign key
CREATE TABLE product_care (
  sku          TEXT PRIMARY KEY REFERENCES products (sku) ON DELETE CASCADE,
  instructions TEXT NOT NULL
);

-- After (3NF): each fact stored once
CREATE TABLE doctors (
    doctor_id  int GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    name       text NOT NULL,
    phone      text NOT NULL
);
CREATE TABLE appointments (
    id         bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    patient_id bigint NOT NULL,
    doctor_id  int    NOT NULL REFERENCES doctors(doctor_id),
    starts_at  timestamptz NOT NULL
);

-- One row, one short transaction, every appointment sees it
UPDATE doctors SET phone = '+44 113 496 0123' WHERE doctor_id = 7;

