-- Snowflake. Create the warehouse first: grants refer to it.
CREATE WAREHOUSE IF NOT EXISTS assistant_wh
  WAREHOUSE_SIZE = 'XSMALL'
  AUTO_SUSPEND = 60              -- seconds idle before it stops billing
  AUTO_RESUME = TRUE
  INITIALLY_SUSPENDED = TRUE;

-- A read-only role for the AI assistant
CREATE ROLE IF NOT EXISTS assistant_reader;
GRANT USAGE ON WAREHOUSE assistant_wh TO ROLE assistant_reader;
GRANT USAGE ON DATABASE analytics TO ROLE assistant_reader;
GRANT USAGE ON SCHEMA analytics.marts TO ROLE assistant_reader;
GRANT SELECT ON ALL TABLES IN SCHEMA analytics.marts TO ROLE assistant_reader;
GRANT SELECT ON FUTURE TABLES IN SCHEMA analytics.marts TO ROLE assistant_reader;
GRANT ROLE assistant_reader TO USER svc_assistant;

-- Column masking: only PII_ADMIN sees real emails
CREATE MASKING POLICY email_mask AS (val STRING) RETURNS STRING ->
  CASE WHEN CURRENT_ROLE() = 'PII_ADMIN' THEN val ELSE '***MASKED***' END;
ALTER TABLE analytics.marts.dim_customer
  MODIFY COLUMN email SET MASKING POLICY email_mask;

-- Row access: a mapping table says which role sees which region
CREATE ROW ACCESS POLICY region_rows AS (row_region STRING) RETURNS BOOLEAN ->
  EXISTS (SELECT 1 FROM security.region_map m
          WHERE m.role_name = CURRENT_ROLE() AND m.region = row_region);
ALTER TABLE analytics.marts.fct_claims ADD ROW ACCESS POLICY region_rows ON (region);

-- Cost attribution
ALTER USER svc_assistant SET QUERY_TAG = 'project:claims-assistant';
SELECT query_tag, COUNT(*) AS queries,
       SUM(total_elapsed_time) / 1000 AS seconds
FROM snowflake.account_usage.query_history
WHERE start_time > DATEADD(day, -7, CURRENT_TIMESTAMP())
GROUP BY query_tag ORDER BY seconds DESC;

-- Test as the role, not by reading the policy
USE ROLE assistant_reader;
SELECT email FROM analytics.marts.dim_customer LIMIT 3;   -- ***MASKED***

# TestClient runs background tasks before it returns, so tests see 'done' at once.
# jobs.py   upload a file, answer 202 at once, let the client poll for the result
import time
import uuid

from fastapi import BackgroundTasks, FastAPI, File, HTTPException, UploadFile

app = FastAPI()
JOBS: dict[str, dict] = {}          # demo only: lost on restart, not shared by workers
MAX_BYTES = 5 * 1024 * 1024         # 5 MB limit for this endpoint

def summarize_document(job_id: str, data: bytes) -> None:
    JOBS[job_id]["status"] = "running"
    time.sleep(2)                                   # pretend this is a slow LLM call
    JOBS[job_id] = {"status": "done", "result": f"Read {len(data)} bytes"}

@app.post("/documents", status_code=202)
async def upload(background: BackgroundTasks, file: UploadFile = File(...)):
    if file.content_type not in ("application/pdf", "text/csv"):
        raise HTTPException(status_code=415, detail="Only PDF or CSV files")
    data = await file.read(MAX_BYTES + 1)           # read at most one byte too many
    if len(data) > MAX_BYTES:
        raise HTTPException(status_code=413, detail="File larger than 5 MB")
    job_id = str(uuid.uuid4())
    JOBS[job_id] = {"status": "queued"}
    background.add_task(summarize_document, job_id, data)
    return {"job_id": job_id, "status_url": f"/jobs/{job_id}"}

@app.get("/jobs/{job_id}")
def job_status(job_id: str):
    job = JOBS.get(job_id)
    if job is None:
        raise HTTPException(status_code=404, detail="Unknown job")
    return job

