resource "aws_vpc" "main" {
  cidr_block           = "10.20.0.0/16"
  enable_dns_hostnames = true
  tags = { Name = "riverside-ai" }
}

resource "aws_subnet" "private_a" {
  vpc_id            = aws_vpc.main.id          # reference another resource
  cidr_block        = "10.20.1.0/24"           # 256 addresses
  availability_zone = "eu-west-1a"
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route_table_association" "private_a" {
  subnet_id      = aws_subnet.private_a.id
  route_table_id = aws_route_table.private.id
}

# Private route to S3 without a NAT gateway
resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.eu-west-1.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private.id]
}

resource "aws_security_group" "api" {            # the group the database rule refers to
  name   = "api"
  vpc_id = aws_vpc.main.id
  egress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]                  # outbound HTTPS only
  }
}

resource "aws_security_group" "db" {
  name   = "db"
  vpc_id = aws_vpc.main.id
  ingress {
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.api.id]  # only from the API
  }
}

data "aws_iam_policy_document" "read_claim_docs" {
  statement {
    effect    = "Allow"
    actions   = ["s3:ListBucket"]
    resources = ["arn:aws:s3:::harbor-claims-documents"]
  }
  statement {
    effect    = "Allow"
    actions   = ["s3:GetObject"]                          # read only
    resources = ["arn:aws:s3:::harbor-claims-documents/*"]  # one bucket's objects
  }
}

resource "aws_iam_policy" "read_claim_docs" {
  name   = "claims-api-read-docs"
  policy = data.aws_iam_policy_document.read_claim_docs.json
}

resource "aws_iam_role_policy_attachment" "attach" {
  role       = aws_iam_role.claims_api.name   # role assumed by the service
  policy_arn = aws_iam_policy.read_claim_docs.arn
}

# Add when the bucket uses a customer-managed KMS key (SSE-KMS)
data "aws_iam_policy_document" "decrypt_claim_docs" {
  statement {
    effect    = "Allow"
    actions   = ["kms:Decrypt"]                 # add kms:GenerateDataKey to write objects
    resources = ["arn:aws:kms:eu-west-1:123456789012:key/1111aaaa-22bb-33cc-44dd-555555eeeeee"]
  }
}

# variables.tf
variable "env" {
  type = string
}
variable "db_instance" {
  type    = string
  default = "db.t3.medium"
}
variable "replicas" {
  type    = number
  default = 2
}

# main.tf: call a reusable module
module "tracking" {
  source      = "./modules/ai_service"
  name        = "tracking-${var.env}"
  db_instance = var.db_instance
  replicas    = var.replicas
  deletion_protection = var.env == "prod"      # true only in production
}

output "api_url" { value = module.tracking.api_url }

# prod.tfvars
#   env = "prod"
#   db_instance = "db.r6g.large"
#   replicas = 3
# terraform plan -var-file=prod.tfvars

terraform {
  required_version = ">= 1.6"
  required_providers {
    aws = { source = "hashicorp/aws", version = "~> 6.0" }   # pin a major version
  }
}

# Use the customer's existing network instead of creating one
data "aws_vpc" "existing" {
  tags = { Name = "riverside-core" }
}
data "aws_subnets" "private" {
  filter {
    name   = "vpc-id"
    values = [data.aws_vpc.existing.id]
  }
  tags = { Tier = "private" }
}

# One bucket per environment, tracked by name
resource "aws_s3_bucket" "env" {
  for_each = toset(["dev", "staging", "prod"])
  bucket   = "crestline-tracking-${each.key}"
}
